-- stochastic-processes implementation for OrnsteinUhlenbeck
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("VectorForgeShared")
local Num = require(Shared:WaitForChild("NumericalKernels"))

local Module = {}
function Module.ExactStep(x,theta,mu,sigma,dt,normalSample)
    Num.Nonnegative(theta,"mean reversion rate"); Num.Nonnegative(sigma,"volatility"); Num.Nonnegative(dt,"time step")
    local decay=math.exp(-theta*dt)
    local variance=if theta>0 then sigma*sigma*(1-decay*decay)/(2*theta) else sigma*sigma*dt
    return mu+(x-mu)*decay+math.sqrt(variance)*normalSample
end


-- Exact OU transition moments: mean=mu+(x-mu)e^(-theta dt), variance=sigma^2(1-e^(-2theta dt))/(2theta).
function Module.TransitionMoments(value, longRunMean, reversionRate, diffusion, dt)
    Num = Num or require(game:GetService("ReplicatedStorage"):WaitForChild("VectorForgeShared"):WaitForChild("NumericalKernels"))
    Num.Nonnegative(reversionRate,"mean reversion rate"); Num.Nonnegative(diffusion,"diffusion coefficient"); Num.Nonnegative(dt,"time interval")
    local decay=math.exp(-reversionRate*dt)
    local mean=longRunMean+(value-longRunMean)*decay
    local variance
    if reversionRate==0 then variance=diffusion*diffusion*dt
    else variance=diffusion*diffusion*(1-decay*decay)/(2*reversionRate) end
    return mean,variance
end

return Module
